window.PAIRS=[{"n":12,"s":0.786,"o":{"i":"공인노2022_31-26-2","t":"근로자는 근로조건의 향상을 위하여 자주적인 단결권ㆍ단체교섭권 및 단체행동권을 가진다.","y":2022,"e":"공인노무사 1차"},"x":{"i":"공인노2019_28-27-5","t":"모든 국민은 근로조건의 향상을 위하여 자주적인 단결권ㆍ단체교섭권 및 단체행동권을 가진다.","y":2019,"e":"공인노무사 1차"}},{"n":12,"s":0.364,"o":{"i":"공인노2024_33-41-2","t":"1953년 제정된 「노동쟁의조정법」에는 쟁의행위 민사면책조항이 있었다.","y":2024,"e":"공인노무사 1차"},"x":{"i":"공인노2024_33-41-1","t":"1953년 제정된 「노동조합법」에는 복수노조 금지조항이 있었다.","y":2024,"e":"공인노무사 1차"}},{"n":5,"s":0.84,"o":{"i":"공인노2022_31-36-3","t":"단체협약의 당사자인 노동조합은 단체협약의 유효기간 중에 단체협약에서 정한 근로 조건 등에 관한 내용의 변경이나 폐지를 요구하는 쟁의행위를 행하지 않을 평화의무를 지고 있다.","y":2022,"e":"공인노무사 1차"},"x":{"i":"공인노2025_34-51-4","t":"단체협약의 당사자인 노동조합은 단체협약의 유효기간 중에 단체협약에서 정한 근로 조건 등에 관한 내용의 변경이나 폐지를 요구하는 쟁의행위를 행하지 않을 평화의무를 부담하지 않는다.","y":2025,"e":"공인노무사 1차"}},{"n":5,"s":0.565,"o":{"i":"공인노2019_28-37-3","t":"행정관청은 단체협약중 위법한 내용이 있는 경우에는 노동위원회의 의결을 얻어 그 시정을 명할 수 있다.","y":2019,"e":"공인노무사 1차"},"x":{"i":"공인노2024_33-53-1","t":"노동위원회는 단체협약중 위법한 내용이 있는 경우에는 그 시정을 명할 수 있다.","y":2024,"e":"공인노무사 1차"}},{"n":5,"s":0.527,"o":{"i":"공인노2025_34-54-2","t":"하나의 사업 또는 사업장에 상시 사용되는 동종의 근로자 반수 이상이 하나의 단체협약의 적용을 받게 된 때에는 당해 사업 또는 사업장에 사용되는 다른 동종의 근로자에 대하여도 당해 단체협약이 적용된다.","y":2025,"e":"공인노무사 1차"},"x":{"i":"공인노2022_31-34-2","t":"하나의 사업장에 상시 사용되는 동종의 근로자 반수 이상이 하나의 단체협약의 적용을 받게 된 때에는 행정관청은 직권으로 다른 동종의 근로자에 대하여도 당해 단체협약을 적용한다는 결정을 하여야 한다.","y":2022,"e":"공인노무사 1차"}},{"n":5,"s":0.46,"o":{"i":"공인노2019_28-37-1","t":"단체협약은 서면으로 작성하여 당사자 쌍방이 서명 또는 날인하여야 한다.","y":2019,"e":"공인노무사 1차"},"x":{"i":"공인노2025_34-49-3","t":"단체협약은 서면으로 작성하여 당사자 쌍방이 서명 또는 날인하여야 하며, 단체협약의 당사자는 단체협약의 체결일부터 15일 이내에 이를 노동위원회에 신고하여야 한다.","y":2025,"e":"공인노무사 1차"}},{"n":2,"s":0.84,"o":{"i":"공인노2026_35-43-4","t":"행정관청은 노동조합에 총회의 소집권자가 없는 경우에 조합원의 3분의 1 이상이 회의에 부의할 사항을 제시하고 소집권자의 지명을 요구한 때에는 15일 이내에 회의의 소집권자를 지명하여야 한다.","y":2026,"e":"공인노무사 1차"},"x":{"i":"공인노2024_33-45-5","t":"행정관청은 노동조합에 총회의 소집권자가 없는 경우에 조합원의 3분의 1 이상이 회의에 부의할 사항을 제시하고 소집권자의 지명을 요구한 때에는 지체없이 회의의 소 집권자를 지명하여야 한다.","y":2024,"e":"공인노무사 1차"}},{"n":2,"s":0.833,"o":{"i":"공인노2017_26-41-1","t":"근로시간 면제 한도를 정하기 위하여 근로시간면제심의위원회를 고용노동부에 둔다.","y":2017,"e":"공인노무사 1차"},"x":{"i":"공인노2022_31-30-4","t":"근로시간면제자에 대한 근로시간 면제 한도를 정하기 위하여 근로시간면제심의위원회를 고용노동부에 둔다.","y":2022,"e":"공인노무사 1차"}},{"n":2,"s":0.614,"o":{"i":"공인노2026_35-44-2","t":"노동조합의 대표자는 그 회계감사원으로 하여금 6월에 1회 이상 당해 노동조합의 모든 재원 및 용도등에 대한 회계감사를 실시하게 하고 그 내용과 감사결과를 전체 조합원에게 공개하여야 한다.","y":2026,"e":"공인노무사 1차"},"x":{"i":"공인노2024_33-47-3","t":"노동조합의 대표자는 그 회계감사원으로 하여금 회계연도마다 당해 노동조합의 모든 재원 및 용도, 주요한 기부자의 성명, 현재의 경리 상황등에 대한 회계감사를 실시하게 하고 그 내용과 감사결과를 전체 조합원에게 공개하여야 한다.","y":2024,"e":"공인노무사 1차"}},{"n":2,"s":0.608,"o":{"i":"공인노2024_33-44-4","t":"행정관청은 설립신고서 또는 규약이 기재사항의 누락등으로 보완이 필요한 경우에는 대통령령이 정하는 바에 따라 20일 이내의 기간을 정하여 보완을 요구하여야 한다.","y":2024,"e":"공인노무사 1차"},"x":{"i":"공인노2026_35-48-1","t":"행정관청은 규약이 기재사항의 누락등으로 보완이 필요한 경우에는 대통령령이 정하는 바에 따라 20일 이내의 기간을 정하여 보완을 요구하여야 하며, 보완된 규약을 접수한 때에는 7일 이내에 신고증을 교부하여야 한다.","y":2026,"e":"공인노무사 1차"}},{"n":4,"s":0.787,"o":{"i":"공인노2019_28-36-5","t":"교섭대표노동조합의 지위 유지기간이 만료되었음에도 불구하고 새로운 교섭대표노동조합이 결정되지 못할 경우 기존 교섭대표노동조합은 새로운 교섭대표노동조합이 결정될 때까지 기존 단체협약의 이행과 관련해서는 교섭대표노동조합의 지위를 유지한다.","y":2019,"e":"공인노무사 1차"},"x":{"i":"공인노2024_33-55-4","t":"교섭대표노동조합의 지위 유지기간이 만료되었음에도 불구하고 새로운 교섭대표노동조합이 결정되지 못할 경우 기존 교섭대표노동조합은 새로운 교섭대표노동조합이 결정될 때까지 기존 단체협약의 갱신을 위한 교섭대표노동조합의 지위를 유지한다.","y":2024,"e":"공인노무사 1차"}},{"n":4,"s":0.763,"o":{"i":"공인노2024_33-55-1","t":"노동조합은 해당 사업 또는 사업장에 단체협약이 2개 이상 있는 경우에는 먼저 이르는 단체협약의 유효기간 만료일 이전 3개월이 되는 날부터 사용자에게 교섭을 요구할 수 있다.","y":2024,"e":"공인노무사 1차"},"x":{"i":"공인노2022_31-31-4","t":"노동조합은 해당 사업에 단체협약이 2개 이상 있는 경우에는 나중에 이르는 단체협약의 유효기간 만료일 이전 3개월이 되는 날부터 사용자에게 교섭을 요구할 수 있다.","y":2022,"e":"공인노무사 1차"}},{"n":4,"s":0.685,"o":{"i":"공인노2025_34-52-4","t":"사용자가 교섭창구 단일화 절차에 참여한 다른 노동조합을 차별한 것으로 인정되는 경우, 그와 같은 차별에 합리적인 이유가 있다는 점은 사용자에게 주장ㆍ증명책임이 있다.","y":2025,"e":"공인노무사 1차"},"x":{"i":"공인노2024_33-54-5","t":"교섭대표노동조합이나 사용자가 교섭창구 단일화 절차에 참여한 다른 노동조합을 차별한 것으로 인정되는 경우, 그와 같은 차별에 합리적인 이유가 있다는 점에 대하여 교섭대표노동조합이나 사용자에게는 주장ㆍ증명책임이 없다.","y":2024,"e":"공인노무사 1차"}},{"n":4,"s":0.662,"o":{"i":"공인노2025_34-53-5","t":"노동조합은 사용자가 교섭요구 사실의 공고를 하지 아니하거나 다르게 공고하는 경우에는 고용노동부령으로 정하는 바에 따라 노동위원회에 시정을 요청할 수 있다.","y":2025,"e":"공인노무사 1차"},"x":{"i":"공인노2026_35-54-3","t":"노동조합은 사용자가 교섭요구 사실의 공고를 하지 아니하거나 다르게 공고하는 경우에는 고용노동부령으로 정하는 바에 따라 행정관청에 이의신청을 제기할 수 있다.","y":2026,"e":"공인노무사 1차"}},{"n":8,"s":0.74,"o":{"i":"공인노2019_28-46-1","t":"노동위원회의 사용자에 대한 부당노동행위 구제명령은 사용자에게 공법상의 의무를 부담시킬 뿐, 직접 노사간의 사법상의 법률관계를 발생 또는 변경시키는 것은 아니다.","y":2019,"e":"공인노무사 1차"},"x":{"i":"공인노2026_35-63-4","t":"노동위원회의 사용자에 대한 부당노동행위 구제명령은 사용자에게 공법상의 의무를 부담시킬 뿐만 아니라, 직접 노사간의 사법상의 법률관계를 발생 또는 변경시키기도 한다.","y":2026,"e":"공인노무사 1차"}},{"n":8,"s":0.733,"o":{"i":"공인노2025_34-62-2","t":"확정된 부당노동행위 구제명령에 위반한 자는 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.","y":2025,"e":"공인노무사 1차"},"x":{"i":"공인노2026_35-63-2","t":"확정된 부당노동행위 구제명령에 위반한 자는 2년 이하의 징역 또는 2천만원 이하의 벌금에 처한다.","y":2026,"e":"공인노무사 1차"}},{"n":8,"s":0.625,"o":{"i":"공인노2024_33-52-4","t":"지배ㆍ개입으로서의 부당노동행위의 성립에 반드시 근로자의 단결권의 침해라는 결과의 발생까지 요하는 것은 아니다.","y":2024,"e":"공인노무사 1차"},"x":{"i":"공인노2026_35-64-1","t":"지배ㆍ개입으로서의 부당노동행위의 성립에는 반드시 근로자의 단결권 침해라는 결과의 발생까지 요한다.","y":2026,"e":"공인노무사 1차"}},{"n":8,"s":0.526,"o":{"i":"공인노2026_35-64-3","t":"부당노동행위 구제의 신청은 부당노동행위가 계속하는 행위인 경우 그 종료일부터 3월 이내에 이를 행하여야 한다.","y":2026,"e":"공인노무사 1차"},"x":{"i":"공인노2025_34-62-1","t":"부당노동행위 구제의 신청은 부당노동행위가 있은 날(계속하는 행위는 그 종료일)부터 6월 이내에 이를 행하여야 한다.","y":2025,"e":"공인노무사 1차"}},{"n":7,"s":0.829,"o":{"i":"공인노2025_34-61-3","t":"공익사업에 있어서의 노동쟁의의 조정은 우선적으로 취급하고 신속히 처리하여야 한다.","y":2025,"e":"공인노무사 1차"},"x":{"i":"공인노2019_28-40-1","t":"공익사업에 있어서의 노동쟁의의 조정은 우선적으로 취급하고 신속히 처리하도록 노력하여야 한다.","y":2019,"e":"공인노무사 1차"}},{"n":7,"s":0.815,"o":{"i":"공인노2024_33-63-5","t":"노동위원회의 중재재정 또는 재심결정은 중앙노동위원회에의 재심신청 또는 행정소송의 제기에 의하여 그 효력이 정지되지 아니한다.","y":2024,"e":"공인노무사 1차"},"x":{"i":"공인노2025_34-66-5","t":"노동위원회의 중재재정 또는 재심결정은 중앙노동위원회에의 재심신청 또는 행정소송의 제기에 의하여 그 효력이 정지된다.","y":2025,"e":"공인노무사 1차"}},{"n":7,"s":0.771,"o":{"i":"공인노2025_34-64-2","t":"노동쟁의가 중재에 회부된 때에는 그 날부터 15일간은 쟁의행위를 할 수 없다.","y":2025,"e":"공인노무사 1차"},"x":{"i":"공인노2022_31-38-1","t":"노동쟁의가 중재에 회부된 때에는 그 날부터 20일간은 쟁의행위를 할 수 없다.","y":2022,"e":"공인노무사 1차"}},{"n":7,"s":0.586,"o":{"i":"공인노2024_33-60-2","t":"노동관계 당사자는 사적 조정에 의하여 노동쟁의를 해결하기로 한 때에는 이를 노동 위원회에 신고하여야 한다.","y":2024,"e":"공인노무사 1차"},"x":{"i":"공인노2017_26-35-2","t":"노동관계 당사자는 사적조정등에 의하여 노동쟁의를 해결하기로 한 때에는 이를 고용노동부장관에게 신고하여야 한다.","y":2017,"e":"공인노무사 1차"}},{"n":6,"s":0.787,"o":{"i":"공인노2017_26-40-1","t":"노동조합의 쟁의행위는 그 조합원의 직접ㆍ비밀ㆍ무기명투표에 의한 조합원 과반수의 찬성으로 결정하지 아니하면 이를 행할 수 없다.","y":2017,"e":"공인노무사 1차"},"x":{"i":"공인노2019_28-42-5","t":"노동조합의 쟁의행위는 그 조합원의 직접ㆍ비밀ㆍ무기명투표에 의한 조합원 3분의 2 이상의 찬성으로 결정하지 아니하면 이를 행할 수 없다.","y":2019,"e":"공인노무사 1차"}},{"n":6,"s":0.708,"o":{"i":"공인노2019_28-43-4","t":"노동조합은 쟁의행위 기간에 대한 임금의 지급을 요구하여 이를 관철할 목적으로 쟁의행위를 하여서는 아니된다.","y":2019,"e":"공인노무사 1차"},"x":{"i":"공인노2022_31-42-4","t":"노동조합은 쟁의행위 기간에 대한 임금의 지급을 요구하여 이를 관철할 목적으로 쟁의 행위를 할 수 있다.","y":2022,"e":"공인노무사 1차"}},{"n":6,"s":0.694,"o":{"i":"공인노2024_33-58-4","t":"노동관계 당사자는 노동쟁의가 발생한 때에는 어느 일방이 이를 상대방에게 서면으로 통보하여야 한다.","y":2024,"e":"공인노무사 1차"},"x":{"i":"공인노2026_35-59-1","t":"노동관계 당사자는 노동쟁의가 발생한 때에는 어느 일방이 이를 노동위원회에 서면으로 통보하여야 한다.","y":2026,"e":"공인노무사 1차"}},{"n":6,"s":0.689,"o":{"i":"공인노2022_31-40-5","t":"사용자의 직장폐쇄가 정당한 쟁의행위로 평가받을 때 비로소 사용자는 직장폐쇄 기간 동안의 대상 근로자에 대한 임금지불의무를 면한다.","y":2022,"e":"공인노무사 1차"},"x":{"i":"공인노2025_34-59-5","t":"사용자는 직장폐쇄가 정당한 쟁의행위로 평가받는지에 관계없이 직장폐쇄 기간 동안의 대상 근로자에 대한 임금지불의무를 면한다.","y":2025,"e":"공인노무사 1차"}},{"n":3,"s":0.425,"o":{"i":"공인노2024_33-48-4","t":"규약에서 정한 해산사유가 발생하여 노동조합이 해산한 때에는 그 대표자는 해산한 날부터 15일 이내에 행정관청에게 이를 신고하여야 한다.","y":2024,"e":"공인노무사 1차"},"x":{"i":"공인노2025_34-45-3","t":"규약에서 정한 해산사유가 발생하여 노동조합이 해산한 때에는 그 대표자가 행정관청에 신고할 때에 해산된 것으로 본다.","y":2025,"e":"공인노무사 1차"}},{"n":3,"s":0.371,"o":{"i":"공인노2025_34-45-5","t":"총회에서 재적조합원 과반수의 출석과 출석조합원 3분의 2 이상의 찬성에 따라 노동조합이 분할로 소멸하는 경우에 해산한다.","y":2025,"e":"공인노무사 1차"},"x":{"i":"공인노2019_28-32-4","t":"노동조합 총회에서 재적조합원 과반수의 출석과 출석조합원 과반수의 찬성으로 노동조합 해산결의가 있는 경우에 노동조합은 해산한다.","y":2019,"e":"공인노무사 1차"}},{"n":10,"s":0.793,"o":{"i":"공인노2026_35-68-4","t":"고충처리위원은 노사를 대표하는 3명 이내의 위원으로 구성한다.","y":2026,"e":"공인노무사 1차"},"x":{"i":"공인노2024_33-72-2","t":"고충처리위원은 노사를 대표하는 5명 이내의 위원으로 구성한다.","y":2024,"e":"공인노무사 1차"}},{"n":10,"s":0.706,"o":{"i":"공인노2024_33-65-5","t":"노사협의회 회의는 근로자위원과 사용자위원 각 과반수의 출석으로 개최하고 출석위원 3분의 2 이상의 찬성으로 의결한다.","y":2024,"e":"공인노무사 1차"},"x":{"i":"공인노2026_35-66-2","t":"회의는 근로자위원과 사용자위원 각 과반수의 출석으로 개최하고 출석위원 과반수의 찬성으로 의결한다.","y":2026,"e":"공인노무사 1차"}},{"n":10,"s":0.607,"o":{"i":"공인노2022_31-50-1","t":"노사협의회는 근로조건에 대한 결정권이 있는 사업이나 사업장 단위로 설치하여야 한다.","y":2022,"e":"공인노무사 1차"},"x":{"i":"공인노2025_34-70-3","t":"노사협의회는 상시(常時) 30명 미만의 근로자를 사용하는 근로조건에 대한 결정권이 있는 사업이나 사업장 단위로 설치하여야 한다.","y":2025,"e":"공인노무사 1차"}},{"n":10,"s":0.385,"o":{"i":"공인노2025_34-67-1","t":"노사협의회는 근로자와 사용자를 대표하는 같은 수의 위원으로 구성하되, 각 3명 이상 10명 이하로 한다.","y":2025,"e":"공인노무사 1차"},"x":{"i":"공인노2017_26-47-5","t":"근로자와 사용자를 대표하는 같은 수의 위원으로 구성하되, 근로자위원 중에는 여성근로자가 1명 이상 포함되어야 한다.","y":2017,"e":"공인노무사 1차"}},{"n":11,"s":0.737,"o":{"i":"공인노2017_26-49-5","t":"노동조합을 설립하려는 사람은 고용노동부장관에게 설립신고서를 제출하여야 한다.","y":2017,"e":"공인노무사 1차"},"x":{"i":"공인노2019_28-49-2","t":"노동조합을 설립하려는 사람은 교육부장관에게 설립신고서를 제출하여야 한다.","y":2019,"e":"공인노무사 1차"}},{"n":11,"s":0.723,"o":{"i":"공인노2022_31-48-4","t":"단체교섭이 결렬된 경우 이를 조정ㆍ중재하기 위하여 중앙노동위원회에 공무원 노동 관계 조정위원회를 둔다.","y":2022,"e":"공인노무사 1차"},"x":{"i":"공인노2024_33-77-1","t":"단체교섭이 결렬된 경우 이를 조정ㆍ중재하기 위하여 중앙노동위원회에 특별조정위원회를 둔다.","y":2024,"e":"공인노무사 1차"}},{"n":11,"s":0.705,"o":{"i":"공인노2024_33-73-2","t":"교원은 임용권자의 동의를 받아 노동조합으로부터 급여를 지급받으면서 노동조합의 업무에만 종사할 수 있다.","y":2024,"e":"공인노무사 1차"},"x":{"i":"공인노2026_35-78-4","t":"교원은 임용권자로부터 급여를 지급받으면서 노동조합의 업무에만 종사할 수 있다.","y":2026,"e":"공인노무사 1차"}},{"n":11,"s":0.674,"o":{"i":"공인노2026_35-79-2","t":"교원의 노동쟁의를 조정ㆍ중재하기 위하여 중앙노동위원회에 교원 노동관계 조정위원회를 둔다.","y":2026,"e":"공인노무사 1차"},"x":{"i":"공인노2025_34-79-2","t":"교원의 노동쟁의를 조정·중재하기 위하여 각 지방노동위원회에 교원 노동관계 조정 위원회를 둔다.","y":2025,"e":"공인노무사 1차"}},{"n":9,"s":0.525,"o":{"i":"공인노2026_35-73-1","t":"화해조서에는 관계 당사자와 화해에 관여한 부문별 위원회의 위원 전원이 모두 서명하거나 날인하여야 한다.","y":2026,"e":"공인노무사 1차"},"x":{"i":"공인노2024_33-68-5","t":"단독심판의 위원을 제외하고 화해에 관여한 부문별 위원회의 위원 전원은 화해조서에 모두 서명하거나 날인하여야 한다.","y":2024,"e":"공인노무사 1차"}},{"n":9,"s":0.397,"o":{"i":"공인노2022_31-47-5","t":"노동위원회법에 따라 작성된 화해조서는 「민사소송법」에 따른 재판상 화해의 효력을 갖는다.","y":2022,"e":"공인노무사 1차"},"x":{"i":"공인노2026_35-73-5","t":"「노동위원회법」에 따라 작성된 화해조서는 「노동조합 및 노동관계조정법」에 따른 중재재정의 효력을 갖는다.","y":2026,"e":"공인노무사 1차"}}];
